-- RD-95: "?" dos campos NOVOS da aba Preço e desconto do Meu painel de vendas (/dashboard/comercial/meu-painel).
-- Spec do CEO 26/11: ganhos na tabela (espelho do desconto), líquido = ganhos − descontos, % simples × ponderado,
-- ganho por cliente/vendedor e detalhe das faixas. O cálculo é feito na tela sobre a fn_bi_comercial_base (sem
-- função nova, sem mexer no tradutor). Esta migration só ACRESCENTA 9 chaves de ajuda (aditiva e idempotente,
-- ON CONFLICT DO NOTHING). Não altera dado de cliente. Linguagem do usuário (RD-95), sem nome de terceiros (RD-100).
-- Code: code-desenvolvedor-3
INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
SELECT v.chave, 'Meu painel de vendas', v.rotulo, v.o_que, v.para_que, v.exemplo, v.erro, v.ordem, '/dashboard/comercial/meu-painel', 'comercial', 'publicado'
FROM (VALUES
 ('com.painel.ganho_tabela', 'Ganho na tabela', 'Indicador calculado — não se preenche.', 'Soma, item a item, quanto o preço praticado ficou ACIMA do preço de tabela do sistema de origem: (preço praticado − preço de tabela) × quantidade. É o espelho do desconto e conta a favor.', 'Vendeu 1.000 kg a R$ 31,00 com tabela de R$ 30,00: ganho de R$ 1.000.', 'Olhar só o desconto: sem o ganho, quem negocia bem para cima parece igual a quem só vende na tabela.', 60),
 ('com.painel.desconto_total', 'Desconto na tabela', 'Indicador calculado — não se preenche.', 'Soma, item a item, quanto o preço praticado ficou ABAIXO do preço de tabela: (preço de tabela − preço praticado) × quantidade. Diferença de até R$ 0,05 não conta (arredondamento).', 'Vendeu 500 kg a R$ 28,00 com tabela de R$ 30,00: desconto de R$ 1.000.', 'Tratar o desconto como prejuízo certo: a tabela de referência pode estar desatualizada; confira o índice vs a média.', 61),
 ('com.painel.liquido_tabela', 'Líquido (ganhos − descontos)', 'Indicador calculado — não se preenche.', 'Saldo real do preço contra a tabela: ganhos menos descontos. Verde (+) = no conjunto vendeu acima da tabela; vermelho (−) = abaixo. O % é o saldo dividido pelo faturamento na tabela.', 'Ganhos de R$ 12 mil e descontos de R$ 30 mil: líquido de −R$ 18 mil.', 'Somar só os descontos e esquecer os ganhos: o saldo mostra o efeito real do preço.', 62),
 ('com.painel.ponderado', 'Média simples × ponderado', 'Indicador calculado — não se preenche.', 'A média simples dá o mesmo peso a cada item vendido. O ponderado pesa pelo tamanho da venda: por faturamento (soma dos R$ de desconto ÷ soma do faturamento na tabela) ou por volume (kg). O ponderado é o que vale para decidir.', 'Uma nota de R$ 200 com 20% de desconto e uma de R$ 50 mil com 1%: simples dá 10,5%, ponderado dá cerca de 1,1%.', 'Decidir pela média simples: uma nota pequena com desconto alto distorce a leitura de quem vende muito.', 63),
 ('com.painel.indice_media', 'Índice médio dos vendedores', 'Indicador calculado — não se preenche.', 'Média do índice de preço dos vendedores. Simples = cada vendedor pesa igual; ponderado = soma do faturamento dividida pela soma do valor esperado ao preço médio, ou seja, quem vende mais pesa mais.', 'Dois vendedores com índice 90 e 110, um vendendo 10 vezes mais que o outro: a média simples é 100, a ponderada fica perto do índice de quem vende mais.', 'Achar que a média simples é a da empresa: a empresa é a ponderada.', 64),
 ('com.painel.faixa_detalhe', 'Detalhe da faixa de preço', 'Toque numa faixa para abrir — não se preenche.', 'Mostra os clientes e vendedores com mais faturamento naquela faixa e o saldo deles contra a tabela (+ ganho, − desconto). Vale para os dois lados: acima da tabela e cada faixa de desconto.', 'Abrir "Acima da tabela" e ver quais clientes aceitam preço acima da referência.', 'Ler o faturamento da faixa como o ganho: o ganho é o saldo ao lado do nome.', 65),
 ('com.painel.preco_vendedor', 'Ganho e desconto por vendedor', 'Indicador calculado — não se preenche.', 'Ranking dos vendedores com o índice vs a média (principal), o índice simples, o ganho e o desconto na tabela em R$ e em % ponderado, e o líquido. Ordene pela coluna que quiser.', 'Vendedor com índice 104 e líquido +R$ 8 mil: vende acima da média e acima da tabela.', 'Comparar vendedores só pelo desconto em R$: quem vende mais tem mais R$ de desconto; use o % ponderado.', 66),
 ('com.painel.ganho_cliente', 'Ganho por cliente', 'Indicador calculado — não se preenche.', 'Clientes que compraram acima da tabela, com o ganho em R$, o % acima ponderado pelo faturamento na tabela do cliente e o % simples (média dos itens). Mostra quem aceita preço melhor.', 'Cliente com ganho de R$ 2.400 e 3,2% acima: dá para manter o preço nele.', 'Usar o % simples para comparar clientes: um item pequeno acima puxa a média sem peso real.', 67),
 ('com.painel.desconto_cliente', 'Desconto por cliente', 'Indicador calculado — não se preenche.', 'Todos os clientes com o desconto em R$ contra a tabela, o % abaixo ponderado pelo faturamento na tabela, o % simples e a parte dos itens vendidos abaixo da tabela. Mostra onde ficou dinheiro na mesa.', 'Cliente com 4% abaixo ponderado e 80% dos itens abaixo: o desconto é sistemático, não pontual.', 'Confundir "itens abaixo" com o % de desconto: um conta itens, o outro mede o tamanho do desconto.', 68)
) AS v(chave, rotulo, o_que, para_que, exemplo, erro, ordem)
ON CONFLICT (chave) DO NOTHING;
